CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email varchar(320) UNIQUE, username varchar(64) NOT NULL UNIQUE, display_name varchar(160) NOT NULL, password_hash text NOT NULL, avatar_url text, role varchar(24) NOT NULL DEFAULT 'user', status varchar(24) NOT NULL DEFAULT 'active', email_verified_at timestamptz, verification_token text, reset_token text, reset_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS role varchar(24) NOT NULL DEFAULT 'user';
ALTER TABLE users ADD COLUMN IF NOT EXISTS status varchar(24) NOT NULL DEFAULT 'active';
ALTER TABLE users ADD COLUMN IF NOT EXISTS email_verified_at timestamptz;
ALTER TABLE users ADD COLUMN IF NOT EXISTS verification_token text;
ALTER TABLE users ADD COLUMN IF NOT EXISTS reset_token text;
ALTER TABLE users ADD COLUMN IF NOT EXISTS reset_expires_at timestamptz;
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), author_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, body text NOT NULL DEFAULT '', audience varchar(24) NOT NULL DEFAULT 'friends', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS posts_author_idx ON posts(author_id);
CREATE INDEX IF NOT EXISTS posts_created_idx ON posts(created_at);
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title varchar(160), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversation_members (conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY (conversation_id, user_id));
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES users(id), body text NOT NULL DEFAULT '', sent_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
CREATE INDEX IF NOT EXISTS messages_conversation_idx ON messages(conversation_id, sent_at);
CREATE TABLE IF NOT EXISTS follows (follower_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, following_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (follower_id, following_id), CHECK (follower_id <> following_id));
CREATE INDEX IF NOT EXISTS follows_following_idx ON follows(following_id);
CREATE TABLE IF NOT EXISTS reactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind varchar(24) NOT NULL DEFAULT 'like', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (post_id, user_id, kind));
CREATE TABLE IF NOT EXISTS comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES users(id), parent_id uuid, body text NOT NULL CHECK (length(body) <= 4000), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS comments_post_idx ON comments(post_id, created_at);
CREATE TABLE IF NOT EXISTS saved_posts (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, post_id));
CREATE TABLE IF NOT EXISTS post_shares (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, actor_id uuid REFERENCES users(id), kind varchar(48) NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id, created_at);
CREATE TABLE IF NOT EXISTS media_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), object_key text NOT NULL UNIQUE, mime_type varchar(120) NOT NULL, size integer NOT NULL CHECK (size >= 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS post_media (post_id uuid NOT NULL REFERENCES posts(id) ON DELETE CASCADE, media_id uuid NOT NULL REFERENCES media_files(id) ON DELETE CASCADE, sort_order integer NOT NULL DEFAULT 0, PRIMARY KEY(post_id, media_id));
CREATE TABLE IF NOT EXISTS message_reads (message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(message_id, user_id));
CREATE TABLE IF NOT EXISTS user_blocks (blocker_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, blocked_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id, blocked_id), CHECK(blocker_id <> blocked_id));
CREATE TABLE IF NOT EXISTS calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), initiator_id uuid NOT NULL REFERENCES users(id), kind varchar(12) NOT NULL CHECK(kind IN ('audio','video')), status varchar(24) NOT NULL DEFAULT 'ringing', started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz);
CREATE TABLE IF NOT EXISTS call_participants (call_id uuid NOT NULL REFERENCES calls(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), joined_at timestamptz, left_at timestamptz, PRIMARY KEY(call_id, user_id));
CREATE TABLE IF NOT EXISTS communities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), name varchar(120) NOT NULL UNIQUE, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_members (community_id uuid NOT NULL REFERENCES communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role varchar(24) NOT NULL DEFAULT 'member', joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(community_id, user_id));
CREATE TABLE IF NOT EXISTS videos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), media_id uuid REFERENCES media_files(id), title varchar(200) NOT NULL, description text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audio_tracks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), media_id uuid REFERENCES media_files(id), title varchar(200) NOT NULL, artist varchar(160) NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS playlists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), name varchar(160) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS marketplace_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), seller_id uuid NOT NULL REFERENCES users(id), title varchar(200) NOT NULL, description text NOT NULL DEFAULT '', price_cents integer NOT NULL CHECK(price_cents >= 0), status varchar(24) NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES users(id), target_type varchar(32) NOT NULL, target_id uuid NOT NULL, reason varchar(120) NOT NULL, details text NOT NULL DEFAULT '', status varchar(24) NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS moderation_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), moderator_id uuid NOT NULL REFERENCES users(id), target_user_id uuid REFERENCES users(id), target_post_id uuid REFERENCES posts(id), action varchar(48) NOT NULL, details text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
